package codes.castled.curios;

import com.google.gson.JsonParser;

import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.Map;

/**
 * Pixel widths of text as the vanilla client draws it in its default font, from the bundled
 * {@code font-widths.json} (generated by {@code pack/tools/font_widths.py} from a client jar). Used
 * to size frame panels to their lines.
 */
final class TextWidth {
    /** Characters outside the bitmap pages come from unifont, whose wide glyphs advance 9. */
    private static final int UNKNOWN_BMP = 6;
    private static final int UNKNOWN_WIDE = 9;

    private static final class Holder {
        static final Map<Integer, Integer> WIDTHS = load();
    }

    private TextWidth() {}

    private static Map<Integer, Integer> load() {
        try (InputStream in = TextWidth.class.getClassLoader().getResourceAsStream("font-widths.json")) {
            if (in == null) throw new IllegalStateException("font-widths.json is missing from the Curios jar");
            Map<Integer, Integer> widths = new HashMap<>();
            for (var entry : JsonParser.parseReader(new InputStreamReader(in, StandardCharsets.UTF_8)).getAsJsonObject().entrySet()) {
                widths.put(entry.getKey().codePointAt(0), entry.getValue().getAsInt());
            }
            return widths;
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** The width of {@code text} in pixels, at normal weight. */
    static int of(String text) {
        if (text == null) return 0;
        int width = 0;
        for (int i = 0; i < text.length(); ) {
            int cp = text.codePointAt(i);
            Integer known = Holder.WIDTHS.get(cp);
            width += known != null ? known : cp > 0xFFFF ? UNKNOWN_WIDE : UNKNOWN_BMP;
            i += Character.charCount(cp);
        }
        return width;
    }
}
